    P('S-TRAINING-TEE', 'Training tee', ['gym'], 35, 'A boxy cotton blend tee for the gym. Heavy enough to hold its shape, light enough to train in. Washes without shrinking.', 'a {value} boxy training t-shirt laid flat', axis='color', values=['Black', 'Grey', 'White'], picture_per_value=True, attributes=dict(sport='Gym', material='Cotton', size='')),
    P('S-YOGA-MAT', 'Cork yoga mat', ['yoga'], 85, 'A 4 mm natural rubber mat with a cork top that grips more when wet. The cork top is naturally antibacterial and grips better as you sweat. It rolls with a cotton strap.', 'a rolled cork yoga mat with a natural rubber base', attributes=dict(sport='Yoga', material='Rubber', color='Tan', size='One size')),
    P('S-RUBBER-MAT', 'Rubber yoga mat', ['yoga', 'gym'], 70, 'A 5 mm natural rubber mat, 183 cm long. Grippy on both sides, cushioned enough for knees. It weighs 2.5 kg.', 'a rolled {value} natural rubber yoga mat', axis='color', values=['Green', 'Charcoal', 'Purple'], picture_per_value=True, attributes=dict(sport='Yoga|Gym', material='Rubber', size='One size')),
