    P('S-ROLLER', 'Foam roller', ['yoga', 'running'], 35, 'A 33 cm medium density roller. Firm enough for legs, forgiving enough for backs. It does not lose its shape.', 'a black textured foam roller', attributes=dict(sport='Yoga|Running|Cycling', material='Rubber', color='Black', size='One size')),
    P('S-MASSAGE-BALL', 'Massage ball set', ['yoga'], 18, 'A lacrosse ball and a peanut, for feet and backs. The ball reaches the small muscles and the peanut sits either side of the spine. Both fit a pocket.', 'a black massage ball and a peanut shaped massage ball', attributes=dict(sport='Yoga|Running', material='Rubber', color='Black', size='One size')),
    P('S-HIKING-BOOT', 'Hiking boot', ['hiking'], 190, 'A waterproof leather boot with a stiff sole and no break-in. Full-grain leather, a waterproof lining and a sole that grips wet rock. Comfortable from the first walk.', 'a {value} leather hiking boot seen from the side', axis='color', values=['Brown', 'Charcoal'], picture_per_value=True, attributes=dict(sport='Hiking', material='Leather', size='')),
    P('S-HIKING-SHOE', 'Hiking shoe', ['hiking'], 140, 'A low waterproof shoe for fast days. Light, waterproof and grippy, for long days at speed. It dries overnight.', 'a grey and green low hiking shoe', axis='size', values=SHOE, attributes=dict(sport='Hiking', material='Recycled polyester', color='Grey')),
    P('S-DAYPACK', 'Daypack 25', ['hiking'], 110, 'A 25 litre pack at 780 g, with a rain cover and a hydration sleeve. Enough room for a day in the hills, with a hip belt that carries the weight. The rain cover lives in its own pocket.', 'a {value} 25 litre hiking daypack', axis='color', values=['Green', 'Blue Dark', 'Orange'], picture_per_value=True, attributes=dict(sport='Hiking', material='Nylon', size='One size')),
    P('S-SHELL', 'Three-layer shell', ['hiking', 'cycling'], 260, 'A 20 000 mm waterproof shell with pit zips and a helmet hood. The kind of jacket you buy once. Pit zips for the climb, a hood that fits a helmet, and a lifetime repair promise.', 'a {value} hooded waterproof shell jacket laid flat', axis='color', values=['Blue', 'Red', 'Black'], picture_per_value=True, attributes=dict(sport='Hiking|Cycling', material='Recycled polyester', size='')),
    P('S-FLEECE', 'Grid fleece', ['hiking', 'running'], 90, 'A light grid fleece that breathes on the climb. The grid traps warmth and lets sweat through. It layers under the shell without bulk.', 'a {value} grid fleece pullover laid flat', axis='color', values=['Green', 'Grey', 'Blue Dark'], picture_per_value=True, attributes=dict(sport='Hiking|Running', material='Recycled polyester', size='')),
    P('S-POLES', 'Carbon poles', ['hiking'], 120, 'Folding carbon poles at 180 g each, with cork grips. They fold into three and fit a pack. The cork grips shape to the hand.', 'a pair of folding carbon trekking poles with cork grips', attributes=dict(sport='Hiking|Running', material='Nylon', color='Black', size='One size')),
    P('S-HIKE-SOCKS', 'Hiking socks, 2 pack', ['hiking'], 26, 'Merino socks with a cushioned sole. Merino with a cushioned sole and a snug arch. No blisters on a three-day walk.', 'two pairs of grey merino hiking socks', axis='size', values=['36', '39', '42', '45'], attributes=dict(sport='Hiking', material='Wool', color='Grey')),
    P('S-GOGGLES', 'Swim goggles', ['swimming'], 32, 'Low-profile goggles with a curved lens and five nose bridges. The curved lens gives a wide view and the five bridges give a real fit. Anti-fog inside.', 'a pair of {value} swimming goggles', axis='color', values=['Black', 'Blue', 'Silver'], picture_per_value=True, attributes=dict(sport='Swimming', material='Rubber', size='One size')),
    P('S-SWIMSUIT', 'Training swimsuit', ['swimming'], 55, 'A chlorine-proof one-piece with a medium back. Chlorine-proof fabric that keeps its shape for a year of mornings. The medium back gives free shoulders.', 'a {value} one piece training swimsuit laid flat', axis='color', values=['Black', 'Blue Dark'], picture_per_value=True, attributes=dict(sport='Swimming', material='Recycled polyester', size='')),
    P('S-JAMMERS', 'Training jammers', ['swimming'], 45, 'Knee-length jammers that last a season of chlorine. A drawstring waist and a fabric that lasts. Quick to dry.', 'a pair of black swimming jammers laid flat', axis='size', values=CLOTH, attributes=dict(sport='Swimming', material='Recycled polyester', color='Black')),
    P('S-SWIM-CAP', 'Silicone cap', ['swimming'], 10, 'A soft silicone cap that does not pull. Soft silicone that goes on without pulling hair. One size.', 'a {value} silicone swim cap', axis='color', values=['Black', 'Blue', 'Pink'], picture_per_value=True, attributes=dict(sport='Swimming', material='Rubber', size='One size')),
    P('S-TOWEL', 'Microfibre towel', ['swimming', 'hiking'], 22, 'A large towel that dries in an hour and packs to a fist. Large enough to wrap, small enough for a pocket. It dries in an hour on a rail.', 'a folded {value} microfibre towel', axis='color', values=['Blue', 'Grey'], picture_per_value=True, attributes=dict(sport='Swimming|Hiking', material='Recycled polyester', size='One size')),
    P('S-TOW-FLOAT', 'Open water tow float', ['swimming'], 30, 'A bright float with a dry pocket, for open water. Bright orange so boats see you, with a dry pocket for keys and a phone. It clips to a waist belt.', 'a bright orange inflatable swim tow float', attributes=dict(sport='Swimming', material='Nylon', color='Orange', size='One size')),
    P('S-HOME-GYM', 'Home gym kit', ['gym'], 330, 'A kettlebell, bands, a rope and a mat. Everything for a full session in a small room. Cheaper than the four bought apart.', 'a kettlebell, resistance bands, a jump rope and a rolled mat arranged together', grouped=['S-KETTLEBELL-16', 'S-BANDS', 'S-JUMP-ROPE', 'S-RUBBER-MAT-CHARCOAL'], attributes=dict(sport='Gym', material='', color='Black', size='One size')),
    P('S-RECOVERY-KIT', 'Recovery kit', ['yoga', 'running'], 60, 'A roller, a ball set and a strap. The three tools our physio uses, in one bag. Ten minutes after each run.', 'a foam roller, two massage balls and a strap arranged together', grouped=['S-ROLLER', 'S-MASSAGE-BALL', 'S-STRAP'], attributes=dict(sport='Yoga|Running', material='Rubber', color='Black', size='One size')),
